// @ts-check
/**
 * `send_feishu_image` — host tool that lets the agent send an image file to
 * the Feishu chat bound to the calling session. The image is typically
 * generated by the agent during the turn (charts, crops, code-rendered PNGs)
 * and lives inside the session workspace.
 *
 * Transport: the Lark channel SDK sends `{ image: { source } }` by uploading
 * the bytes itself. A `Buffer` source needs no `outbound.allowedFileDirs`
 * config (the local-file path branch does), so we always read the file and
 * pass a Buffer — minimal configuration surface, same result.
 *
 * Security: the path is resolved against the calling session's workspace and
 * confined to it (relative() check, same as the loopback image route).
 * @module dsh-fschannel/send-image-tool
 */

import { readFileSync } from 'node:fs'
import { isAbsolute, relative, resolve } from 'node:path'
import { mediaTypeOf, STAGED_EXTENSIONS } from './images.js'

/** @typedef {import('./locales.js').LocaleDict} LocaleDict */

/**
 * Build the tool definition bound to one plugin instance. The definition is a
 * plain object matching the host's `ToolDefinition` shape (name/description/
 * parameters JSON Schema + output declaration + execute) — the plugin does not
 * depend on the `@deepseek-ai/dsh-tools` package, which lives in the host
 * bundle; the registry validates the object at registration.
 * @param {{
 *   store: import('./bindings.js').BindingStore,
 *   channel: () => import('@larksuite/channel').LarkChannel | undefined,
 *   sessionCwd: (sessionId: string) => string | undefined,
 *   indexImage: (record: import('./bindings.js').BindingRecord, file: { path: string, name?: string, bytes: number, mediaType: string }) => void,
 *   ui: () => LocaleDict,
 *   log: (line: string) => void,
 * }} deps - plugin-owned accessors (functions so the live values are read at
 *   call time, not at registration time).
 * @returns {{
 *   name: string, description: string, parameters: Record<string, unknown>,
 *   output: { schema: Record<string, unknown>, render: (args: unknown, value: { ok: boolean, message: string }) => Array<{ type: string, text: string }> },
 *   execute: (args: { path?: string, caption?: string }, exec: { agent?: { sessionId?: string } }) => Promise<{ ok: boolean, message: string }>,
 * }} registry-ready definition.
 */
export function createSendImageTool({ store, channel, sessionCwd, indexImage, ui, log }) {
  return {
    name: 'send_feishu_image',
    description: 'Send an image file (PNG/JPEG/WebP/GIF) to the Feishu chat bound to the current session. The image must be a real file inside the session workspace — e.g. one you generated earlier in this turn. Optionally attach a short caption. Returns whether the image was delivered.',
    parameters: {
      type: 'object',
      additionalProperties: false,
      required: ['path'],
      properties: {
        path: { type: 'string', description: 'Path to the image file: absolute, or relative to the session workspace.' },
        caption: { type: 'string', description: 'Optional short text sent together with the image.' },
      },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        // Requiredness belongs on the object, never on the property. A
        // per-property `required: true` is draft-03 syntax; dsh-tools rejects
        // it outright ("required is not supported on type ..."), and the whole
        // plugin tree then fails to load.
        required: ['ok', 'message'],
        properties: {
          ok: { type: 'boolean', description: 'Whether the image was delivered.' },
          message: { type: 'string', description: 'Human-readable result, shown to the agent.' },
        },
      },
      render: (_args, value) => [{ type: 'text', text: value.message }],
    },
    execute: async ({ path, caption }, exec) => {
      const dict = ui()
      const fail = (message) => ({ ok: false, message })

      const sessionId = exec.agent?.sessionId
      if (typeof sessionId !== 'string' || sessionId === '') {
        return fail(dict.sendImageNoSession)
      }
      const record = store.getBySession(sessionId)
      if (record === undefined) {
        return fail(dict.sendImageUnbound)
      }
      const lark = channel()
      if (lark === undefined) {
        return fail(dict.botNotConnected)
      }

      // Resolve the file path against the session workspace and confine it.
      const raw = typeof path === 'string' && path !== '' ? path : ''
      if (raw === '') return fail(dict.sendImageNoPath)
      const cwd = sessionCwd(sessionId)
      const abs = isAbsolute(raw) ? raw : cwd === undefined ? undefined : resolve(cwd, raw)
      if (abs === undefined) {
        return fail(dict.sendImageOutsideWorkspace)
      }
      if (cwd !== undefined) {
        const rel = relative(cwd, abs)
        // Confine to the workspace: `..` traversal, and Windows cross-drive
        // paths (relative() returns the absolute target for a different root).
        if (rel === '' || rel.startsWith('..') || rel.includes('..\\') || rel.includes('../') || isAbsolute(rel)) {
          return fail(dict.sendImageOutsideWorkspace)
        }
      }

      // Type check by extension (mirror of the staging validation).
      const extension = abs.toLowerCase().split('.').pop()
      const mediaType = mediaTypeOf(undefined, extension)
      if (mediaType === undefined || !STAGED_EXTENSIONS.includes(String(extension))) {
        return fail(dict.sendImageInvalidType)
      }

      let buffer
      try {
        buffer = readFileSync(abs)
      } catch {
        return fail(dict.sendImageNotFound)
      }
      if (buffer.byteLength === 0) return fail(dict.sendImageNotFound)

      try {
        await lark.send(record.chatId, {
          image: { source: buffer },
        }, { replyTo: record.lastInboundMessageId })
      } catch (error) {
        log(`feishu: send_feishu_image failed for ${sessionId}: ${error instanceof Error ? error.message : String(error)}`)
        return fail(dict.sendImageFailed)
      }

      // Index into the gallery so the Web surface shows it too.
      try {
        indexImage(record, { path: abs, bytes: buffer.byteLength, mediaType, name: basenameOf(abs) })
      } catch (error) {
        log(`feishu: send_feishu_image index failed for ${sessionId}: ${error instanceof Error ? error.message : String(error)}`)
      }

      const captionText = typeof caption === 'string' && caption !== '' ? caption.trim() : ''
      if (captionText !== '') {
        try {
          await lark.send(record.chatId, { text: captionText }, { replyTo: record.lastInboundMessageId })
        } catch (error) {
          log(`feishu: send_feishu_image caption failed for ${sessionId}: ${error instanceof Error ? error.message : String(error)}`)
        }
      }
      return { ok: true, message: dict.sendImageSent }
    },
  }
}

/** @param {string} path */
function basenameOf(path) {
  const parts = path.split(/[\\/]/)
  return parts[parts.length - 1] ?? ''
}
